'use strict';
const STORAGE='nn-independent-admin-v1';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
let db,startupNotice='',recoveryRaw='',storageBlocked=false,storedRaw='',upgradeNeeded=false;
try{storedRaw=localStorage.getItem(STORAGE)||'';const saved=storedRaw?JSON.parse(storedRaw):null;db=Model.prepare(storedRaw?saved:makeSeed());if(saved&&saved.version!==Model.VERSION){upgradeNeeded=true;recoveryRaw=storedRaw;startupNotice='演示数据已升级，原始备份可在“原型数据”中导出。';}}
catch(e){recoveryRaw=storedRaw;db=Model.prepare(makeSeed());startupNotice='原有数据无法读取，已保留原始内容并载入演示数据。原因：'+e.message;}
if(recoveryRaw)try{localStorage.setItem(STORAGE+'-recovery',recoveryRaw);if(upgradeNeeded)localStorage.setItem(STORAGE,JSON.stringify(db));}catch{storageBlocked=true;startupNotice+=' 浏览器存储空间不足，尚未覆盖原存档；请先导出原始备份，释放空间后刷新。';}

let current='products',parentId='',parentName='',page=1,pageSize=10,filters={},visited=[],modalSeq=0,forms=new Map(),activeSubtab='',toastTimer,lastCommitError='',showAllProductColumns=false,currentRoute=Model.routeInfo(location.hash);
const rowName=(key,r)=>r[NAME_KEYS[key]]||r[SCHEMA[key]?.columns?.[0]]||r.uid;
const dateNow=()=>new Date().toLocaleString('sv-SE');
function toast(msg,bad=false){const t=$('#toast');t.textContent=msg;t.style.display='block';t.style.background=bad?'#fff1f1':'#f1fcf5';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',3600);}
function commit(action,mutator){const before=clone(db);try{lastCommitError='';if(storageBlocked)throw new Error('请先在原型数据中导出原始备份，释放浏览器存储空间后刷新');mutator();const errors=Model.validate(db);if(errors.length)throw new Error(errors.slice(0,3).join('；'));Model.refresh(db);db.audit.unshift({time:dateNow(),action,operator:'演示运营'});db.audit=db.audit.slice(0,300);localStorage.setItem(STORAGE,JSON.stringify(db));return true;}catch(e){db=before;lastCommitError=e.message;toast('保存失败：'+e.message,true);return false;}}
function navigate(key,params={}){const q=new URLSearchParams(params).toString();location.hash=ROUTES[key]+(q?'?'+q:'');}
function route(){currentRoute=Model.routeInfo(location.hash);current=currentRoute.key;parentId=currentRoute.parent;const context=Model.parentContext(db,currentRoute);parentName=context.parent?rowName(context.parentKey,context.parent):'';page=1;filters=current==='products'?{'商品类型':'独立商品'}:{};activeSubtab='';$('#overlays').innerHTML='';forms.clear();if(!visited.some(r=>r.identity===currentRoute.identity))visited.push({...currentRoute});render();}
function renderNav(){const query=$('#menuSearch').value.trim();$('#nav').innerHTML=GROUPS.map(([group,keys])=>{const list=keys.filter(k=>!query||SCHEMA[k].name.includes(query)||group.includes(query));return list.length?`<details ${query||keys.includes(current)||keys.includes(SCHEMA[current]?.parent)?'open':''}><summary>${esc(group)}</summary>${list.map(k=>`<a href="#${ROUTES[k]}" class="${current===k||SCHEMA[current]?.parent===k?'active':''}">${esc(SCHEMA[k].name)}</a>`).join('')}</details>`:'';}).join('');const group=GROUPS.find(g=>g[1].includes(current)||g[1].includes(SCHEMA[current]?.parent))?.[0]||'商品管理';$('#crumb').textContent=group+' / '+SCHEMA[current].name;$('#tabs').innerHTML=visited.map(r=>{const ctx=Model.parentContext(db,r);return `<a href="${esc(Model.routeHref(r.key,r.parent,r.source))}" class="${r.identity===currentRoute.identity?'active':''}">${esc(SCHEMA[r.key].name)}${ctx.parent?' · '+esc(rowName(ctx.parentKey,ctx.parent)):''}</a>`;}).join('');}
function optValues(spec,draft={},key=current,field=''){return Array.isArray(spec)?spec:Model.choices(db,spec,key,field,draft);}
function options(spec,value,empty='请选择',draft={},key=current,field=''){const all=optValues(spec,draft,key,field),selected=Array.isArray(value)?value:[value];return `<option value="">${empty}</option>`+all.map(v=>{const id=typeof v==='object'?v.uid:v,name=typeof v==='object'?rowName(spec,v):v,duplicate=typeof v==='object'&&all.filter(r=>rowName(spec,r)===name).length>1;return `<option ${selected.includes(id)?'selected':''} value="${esc(id)}">${esc(name)}${duplicate?' · '+esc(id):''}</option>`;}).join('');}
function field(f,value='',id='',isFilter=false,draft={}){const n=esc(f.label),req=f.required&&!isFilter?'required':'',label=`<span class="${req?'required':''}">${n}</span>`;let control='';const attrs=`name="${n}" aria-label="${n}" ${req}`;
 if(f.label==='steamId'&&!isFilter){control=`<div class="inline"><input ${attrs} value="${esc(value)}" placeholder="DEMO-STEAM-1"><button type="button" class="btn small" data-action="steamLookup" data-form="${id}">检索</button><button type="button" class="btn small" data-action="steamLookup" data-form="${id}">获取</button></div><div class="field-help">使用 DEMO-STEAM-1 可体验资料填充；仅检索本地演示资料。</div>`;}else if(f.type==='range'){const vals=Array.isArray(value)?value:['',''];control=`<div class="inline"><input type="${isFilter?'date':'datetime-local'}" name="${n}开始" aria-label="${n}开始" value="${esc(vals[0])}" ${req}><span>至</span><input type="${isFilter?'date':'datetime-local'}" name="${n}结束" aria-label="${n}结束" value="${esc(vals[1])}" ${req}></div>`;}
 else if(f.type==='select'||f.type==='multi'){control=`<select ${attrs} ${f.type==='multi'?'multiple':''}>${options(!isFilter&&typeof f.options==='string'?(Model.relations(forms.get(id)?.key||current,draft)[f.label]?.target||f.options):f.options,value,isFilter?'全部':'请选择',draft,forms.get(id)?.key||current,f.label)}</select>${f.type==='multi'?'<div class="field-help">点击展开后可勾选多个选项。</div>':''}`;}
 else if(f.type==='richtext')control=`<div class="rich-wrap"><div class="rich-toolbar">${[['bold','加粗'],['italic','斜体'],['insertUnorderedList','列表'],['removeFormat','清除格式']].map(([cmd,label])=>`<button type="button" class="btn small" data-rich-command="${cmd}">${label}</button>`).join('')}</div><div class="rich-editor" contenteditable="true" role="textbox" aria-label="${n}" data-editor="${n}">${safeRich(value)}</div></div>`;
 else if(f.type==='platformBindings')control=`<div id="platforms-${id}" class="stack">${platformRows(Array.isArray(value)?value:[])}</div><button type="button" class="btn small" data-action="addPlatform" data-form="${id}">＋ 添加平台</button>`;
 else if(f.type==='textarea')control=`<textarea ${attrs} placeholder="请输入${n}">${esc(value)}</textarea>`;
 else if(f.type==='readonly')control=`<input ${attrs} value="${esc(value)}" readonly>`;
 else if(f.type==='image'||f.type==='video')control=`<input type="file" ${attrs} accept="${f.type==='image'?'image/png,image/jpeg,image/webp':'video/mp4,video/webm'}" data-upload="${n}" data-form="${id}"><div class="field-help">${f.type==='image'?'支持 JPG、PNG、WebP，单张不超过 2 MB。':'支持 MP4、WebM；演示仅记录文件名。'}</div><div data-preview="${n}">${typeof value==='string'&&value.startsWith('data:image/')?`<img class="preview-img" src="${esc(value)}" alt="图片预览">`:esc(value&& !value.startsWith('data:')?value:'')}</div>`;
 else if(f.type==='productPicker')control=`<div id="picked-${id}" class="stack">${pickedHtml(Array.isArray(value)?value:[],id)}</div><button type="button" class="btn small" data-action="picker" data-form="${id}">＋ 选择商品</button>`;
 else if(f.type==='currency')control=`<div id="currencies-${id}" class="stack">${currencyHtml(value,id)}</div><button type="button" class="btn small" data-action="addCurrency" data-form="${id}">＋ 币种添加</button>`;
 else control=`<input ${attrs} type="${f.type==='number'?'number':f.type==='date'?'date':f.type==='datetime-local'?'datetime-local':'text'}" ${f.type==='number'?'min="0" step="any"':''} value="${esc(value)}" placeholder="${isFilter?'请输入':'请输入'+n}">`;
 return `<div class="field ${['textarea','richtext','platformBindings','productPicker','currency','range'].includes(f.type)?'span2':''}" data-field="${n}">${label}${control}</div>`;
}
function filterHtml(s){return s.filters?.length?`<form id="filterForm" class="panel"><div class="filters">${s.filters.map(f=>field(f,filters[f.label]||'','',true)).join('')}</div><div class="filter-actions"><button class="btn primary" type="submit">查询</button><button class="btn" type="button" data-action="resetFilters">重置</button></div></form>`:'';}
function getRows(key=current){if(!SCHEMA[key]?.parent)return [...(db[key]||[])];if(!Model.parentContext(db,{...currentRoute,key,parent:parentId}).valid)return [];return key==='stock'?Model.stockRows(db,currentRoute.source?'source':'batch',parentId):(db[key]||[]).filter(r=>r.parentId===parentId);}
function activeSchema(){return current==='stock'&&activeSubtab==='out'?{...SCHEMA.stock,filters:ListInteractions.outflowFilters,columns:ListInteractions.outflowColumns}:SCHEMA[current];}
function filteredRows(){if(current==='stock'&&activeSubtab==='out')return ListInteractions.outflowRows(db,currentRoute,filters);return getRows().filter(row=>Object.entries(filters).every(([label,value])=>Model.matches(db,current,row,label,value,SCHEMA[current].filters?.find(f=>f.label===label))));}
function fmt(v){if(Array.isArray(v))return v.map(x=>typeof x==='object'?JSON.stringify(x):x).join(' / ');return v===''||v==null?'—':String(v);}
function badge(v){const good=/^(启用|开启|上架|已启用|已上架|已完成|已支付|退款成功|已认证|未使用|正常)$/.test(v),bad=/失败|黑名单/.test(v),warn=/待|中$/.test(v);return `<span class="badge ${good?'good':bad?'bad':warn?'warn':''}">${esc(v)}</span>`;}
function actionHtml(key,row){return (SCHEMA[key].actions||[]).map(action=>{let label=action;if(['启禁','上下架','开关','活动状态'].includes(action)){const state=Model.statusAction(key,row);if(!state)return '';label=state.label;}if(action==='货源管理'&&row['合作方式']==='接口')label='货源列表';return `<button class="link-btn ${label==='删除'?'danger':''}" data-action="row" data-key="${key}" data-id="${esc(row.uid)}" data-op="${esc(action)}">${label}</button>`;}).join('');}
function tableHtml(data,key=current){const s=SCHEMA[key],cols=key==='products'&&!showAllProductColumns?['商品ID','商品名称','人民币售价','库存','销量','状态']:s.columns;return `<div class="table-wrap"><table class="${key==='products'&&!showAllProductColumns?'product-compact':''}"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}${s.actions?.length?'<th class="actions-cell">操作</th>':''}</tr></thead><tbody>${data.map(r=>`<tr>${cols.map(c=>{let cell=esc(fmt(r[c]));if(/状态|实名认证/.test(c))cell=badge(fmt(r[c]));if(key==='products'&&c==='商品名称')cell=`<div class="product-cell"><span class="cover">${esc(r[c].slice(0,2))}</span><div><strong>${esc(r[c])}</strong><small>${esc(r['商品子标题'])}</small></div>`;if(c==='头像')cell=r[c]?.startsWith('data:image/')?`<img class="preview-img" src="${esc(r[c])}" alt="头像">`:'<span class="badge blue">演</span>';if(c==='供货商信息')cell=`${esc(fmt(r[c]))}`;return `<td class="${['商品名称','描述','角色说明','退款原因','文章标题'].includes(c)?'wrap':''}">${cell}</td>`;}).join('')}${s.actions?.length?`<td class="actions-cell">${actionHtml(key,r)}</td>`:''}</tr>`).join('')||`<tr><td colspan="${cols.length+1}" class="empty">暂无数据${s.add?'，可以点击“新增”创建记录':''}</td></tr>`}</tbody></table></div>`;}
function render(){renderNav();if(current==='home')return renderHome();if(current==='cardQuery')return renderCardQuery();const s=activeSchema();if(!Model.parentContext(db,currentRoute).valid){$('#content').innerHTML=`<section class="panel panel-pad"><h1>${esc(s.name)}</h1><p>请从上级记录进入，当前地址缺少有效的关联对象。</p><button class="btn" data-action="backParent">返回上级</button></section>`;return;}const all=filteredRows(),pagination=ListInteractions.paginate(all,page,pageSize),pages=pagination.pages;page=pagination.page;let extra='';if(current==='auth')extra=authGlobalHtml();if(current==='stock')extra=`<div class="tabs"><button class="${activeSubtab!=='out'?'active':''}" data-action="stockTab" data-tab="stock">库存管理</button><button class="${activeSubtab==='out'?'active':''}" data-action="stockTab" data-tab="out">出库记录</button></div>`;
 const toolbar=`${current==='apiSources'?'<button class="btn primary" data-action="syncSources">同步货源</button>':''}${s.parent?'<button class="btn" data-action="backParent">← 返回上级</button>':''}${s.add?'<button class="btn primary" data-action="new">＋ 新增</button>':''}${s.export?'<button class="btn" data-action="export">导出列表</button>':''}${s.stats?'<button class="btn" data-action="stats">统计</button><button class="btn" data-action="statJobs">统计列表</button><button class="btn" data-action="exportJobs">导出记录</button>':''}${current==='recommend'?'<button class="btn" data-action="columns">栏目列表</button>':''}${current==='dict'?'<button class="btn" data-action="dictImport">导入</button><button class="btn" data-action="cache">刷新缓存</button><button class="btn" data-action="trash">回收站</button>':''}`;
 const stats=current==='products'?`<div class="stats">${[['商品总数',db.products.length,'总'],['上架商品',db.products.filter(r=>r['状态']==='上架').length,'上'],['下架商品',db.products.filter(r=>r['状态']==='下架').length,'下'],['组合商品',db.products.filter(r=>r['商品类型']==='组合商品').length,'组']].map(v=>`<div class="stat"><div><small>${v[0]}</small><strong>${v[1]}</strong></div><span class="stat-icon">${v[2]}</span></div>`).join('')}</div>`:'';
 $('#content').innerHTML=`<div class="page-head"><div><h1>${esc(s.name)}${parentName?` <span class="muted" style="font-size:16px"> / ${esc(parentName)}</span>`:''}</h1><p>${esc(s.desc||'')}</p></div><div class="btn-row">${toolbar}</div></div>${extra}${filterHtml(s)}${stats}<section class="panel"><div class="panel-title"><h3>${esc(s.name)}数据</h3><div class="inline">${current==='products'?`<span class="muted">${showAllProductColumns?'可横向滚动查看全部字段':''}</span><button class="btn small" data-action="productColumns">${showAllProductColumns?'显示常用字段':'显示全部字段'}</button>`:''}<span class="muted">共 ${all.length} 条</span></div></div>${current==='stock'&&activeSubtab==='out'?simpleTable(pagination.rows,ListInteractions.outflowColumns):tableHtml(all.slice((page-1)*pageSize,page*pageSize))}<div class="pagination"><span class="muted">共 ${all.length} 条</span><button class="btn small" data-action="page" data-delta="-1" ${page===1?'disabled':''}>上一页</button><span>${page} / ${pages}</span><button class="btn small" data-action="page" data-delta="1" ${page===pages?'disabled':''}>下一页</button><select id="pageSize" aria-label="每页条数">${[10,20,50].map(n=>`<option ${n===pageSize?'selected':''} value="${n}">${n} 条/页</option>`).join('')}</select></div></section>`;
}
function simpleTable(data,cols){return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr>${cols.map(c=>`<td>${esc(fmt(r[c]))}</td>`).join('')}</tr>`).join('')||`<tr><td class="empty" colspan="${cols.length}">暂无数据</td></tr>`}</tbody></table></div>`;}
function renderHome(){$('#content').innerHTML=`<section class="welcome panel"><h1>首页</h1><p>独立站游戏交易管理后台</p><div class="shortcut-grid">${['products','suppliers','orders','recommend','games','articles'].map(k=>`<a class="shortcut" href="#${ROUTES[k]}"><h3>${SCHEMA[k].name} <span style="float:right;color:#1f6feb">→</span></h3></a>`).join('')}</div></section>`;}
function modal(title,body,footer='',wide=false){const id='modal-'+(++modalSeq);$('#overlays').insertAdjacentHTML('beforeend',`<div class="overlay" id="${id}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><section class="modal ${wide?'wide':''}"><header class="modal-head"><h2>${esc(title)}</h2><button class="close-btn" data-action="close" aria-label="关闭">×</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-foot">${footer}</footer>`:''}</section></div>`);setTimeout(()=>{const root=$('#'+id);if(!root)return;const selector='input:not([type=file]),select:not(.sc-native),button,textarea,[contenteditable="true"]',controls=[...root.querySelector('.modal-body').querySelectorAll(selector),...root.querySelectorAll('.modal-foot button,.modal-head button')];controls.find(e=>!e.disabled&&!e.hidden&&!e.classList.contains('sc-native')&&!e.closest('[hidden]')&&e.getClientRects().length)?.focus();},0);return id;}
function closeModal(id){const el=id?$('#'+id):$$('.overlay').at(-1);if(el)el.remove();}
function confirmAction(title,text,callback){const id=modal(title,`<p>${esc(text)}</p>`,`<button class="btn" data-action="close">取消</button><button class="btn primary">确认</button>`);$('#'+id+' .btn.primary').onclick=()=>{callback();closeModal(id);};}
function openForm(key,id=null,defaults={}){if(!id&&SCHEMA[key].parent&&!Model.parentContext(db,{...currentRoute,key}).valid)return toast('请先选择上级记录',true);const row=id?(db[key]||[]).find(x=>x.uid===id):null,draft=row?Model.formDraft(db,key,row):clone({...defaults,parentId,'状态':key==='products'||key==='sources'||key==='batches'?'下架':key==='recommend'?'禁用':'启用'}),fid='form-'+Date.now()+'-'+modalSeq;const fields=key==='products'?PRODUCT_FIELDS:SCHEMA[key].fields;if(!fields)return toast('此页面没有编辑表单',true);if(!row){const defaultsByKey={products:{'商品类型':'独立商品','账号类型':'CDK','货源卡密类型':'CDK','状态':'上架'},sources:{'商品库存':0},batches:{'商品库存':0},tags:{'状态':'开启'},auth:{'生效范围':'全部','生效状态':'启用','选择模块':[]},channels:{'渠道状态':'启用'},promotions:{'控制状态':'禁用','关联成本价':'否'},dictItems:{'key类型':'文本','是否启用':'启用'},subcategories:{'商品类别':db.categories.find(c=>c.uid===parentId)?.['商品类别']||''}};Object.assign(draft,defaultsByKey[key]||{});}forms.set(fid,{key,rowId:id,draft,fields});
 const content=`<form id="${fid}" class="record-form" data-form="${fid}" novalidate><div class="error-msg" role="alert" tabindex="-1" hidden></div><div class="form-grid">${fields.map((f,i)=>`${key==='products'&&[0,6,13].includes(i)?`<div class="section-title span2">${i===0?'基础信息':i===6?'商品类型':'商品信息'}</div>`:''}${field(f,draft[f.label]??(f.type==='number'?0:''),fid,false,draft)}`).join('')}</div></form>`;
 const title=(id?'编辑':'新增')+SCHEMA[key].name;modal(title,content,`<button class="btn" data-action="close">取消</button><button class="btn primary" type="submit" form="${fid}">保存</button>`,SCHEMA[key].full||key==='recommend');updateDependencies(fid);}
function readForm(fid){const state=forms.get(fid),form=$('#'+fid),out={...state.draft};for(const f of state.fields){const el=form.elements.namedItem(f.label);if(f.type==='range'){out[f.label]=[form.elements.namedItem(f.label+'开始')?.value||'',form.elements.namedItem(f.label+'结束')?.value||''];}else if(f.type==='multi'){out[f.label]=el?[...el.selectedOptions].map(o=>o.value).filter(Boolean):[];}else if(f.type==='richtext'){out[f.label]=safeRich([...form.querySelectorAll('[data-editor]')].find(e=>e.dataset.editor===f.label)?.innerHTML||'');}else if(f.type==='platformBindings'){out[f.label]=[...form.querySelectorAll('.platform-binding')].map(r=>({platform:r.querySelector('select').value,gameId:r.querySelector('input').value}));}else if(['image','video','productPicker','currency'].includes(f.type))continue;else out[f.label]=el?.value??out[f.label]??'';if(f.type==='number'&&out[f.label]!=='')out[f.label]=Number(out[f.label]);}out['币种价格']=getCurrencies(fid);return out;}
function selectAvailability(select,reason='暂无可选项'){if(!select)return;const empty=![...select.options].some(o=>o.value&&!o.disabled);select.disabled=empty||Boolean(select.closest('[data-field]')?.hidden);select.dataset.emptyHint=empty?reason:'';if(empty&&select.options[0])select.options[0].textContent=reason;}
function updateDependencies(fid,changed=''){const state=forms.get(fid),form=$('#'+fid);if(!state||!form)return;const value=n=>form.elements.namedItem(n)?.value;const toggle=(name,show)=>{const w=[...form.querySelectorAll('[data-field]')].find(e=>e.dataset.field===name);if(w){w.hidden=!show;w.querySelectorAll('input,select,textarea,button').forEach(e=>e.disabled=!show);}};
 const dependent=(label,spec,parentLabel,parentPrompt,emptyPrompt)=>{const el=form.elements.namedItem(label);if(!el)return;if(changed===parentLabel)el.innerHTML=options(spec,'','请选择',{...state.draft,[parentLabel]:value(parentLabel)},state.key,label);selectAvailability(el,value(parentLabel)?emptyPrompt:parentPrompt);};
 if(state.key==='products'){const combo=value('商品类型')==='组合商品';['账号类型','货源卡密类型','商品分类','商品子分类'].forEach(n=>toggle(n,!combo));['选择商品','生效时间'].forEach(n=>toggle(n,combo));dependent('版本','versions','绑定游戏类别','请先选择游戏类别','该游戏暂无版本');dependent('商品子分类','subcategories','商品分类','请先选择商品分类','该分类暂无子分类');if(changed==='账号类型'){form.elements.namedItem('货源卡密类型').innerHTML=options([value('账号类型')],value('账号类型'),'请选择');}}
 if(state.key==='auth')toggle('选择模块',value('生效范围')==='部分');
 if(state.key==='dictItems'){toggle('key图片',value('key类型')==='图片');toggle('key',value('key类型')!=='图片');}
 if(state.key==='suppliers')toggle('选择服务商',value('合作方式')==='接口');
 if(state.key==='articles'){toggle('指定游戏/平台',value('指定范围')!=='不绑定');if(changed==='指定范围')form.elements.namedItem('指定游戏/平台').innerHTML=options(value('指定范围')==='游戏'?'games':'platforms','','请选择');selectAvailability(form.elements.namedItem('指定游戏/平台'),'暂无可绑定的'+(value('指定范围')==='游戏'?'游戏':'平台'));}
 if(state.key==='promotions')dependent('关联货源','sources','供应商','请先选择供应商','该供应商暂无货源');
 if(state.key==='permissions'){toggle('父级菜单',value('菜单类型')!=='一级菜单');if(changed==='菜单类型')form.elements.namedItem('父级菜单').innerHTML=options('permissions','','请选择',{...state.draft,'菜单类型':value('菜单类型')},'permissions');selectAvailability(form.elements.namedItem('父级菜单'),'暂无可选父级菜单');}
 if(typeof SelectControls!=='undefined')SelectControls.refresh(form);
}
function validation(key,draft,state){const fid=[...forms.entries()].find(([,v])=>v===state)?.[0],form=$('#'+fid);for(const input of form.querySelectorAll('input')){if(input.disabled||input.hidden||input.closest('[hidden]')||!input.validity?.badInput)continue;const field=input.closest('[data-field]')?.dataset.field||input.name||input.getAttribute('aria-label')||'输入';return {field,message:`${field}输入格式无效，请检查后重试`};}const hiddenFields=[...form.querySelectorAll('[data-field]')].filter(e=>e.hidden).map(e=>e.dataset.field),currencies=[...form.querySelectorAll('.currency-row')].map(r=>({currency:r.querySelector('select').value,price:r.querySelectorAll('input')[0].value,original:r.querySelectorAll('input')[1].value}));const issue=FormValidation.validate(key,draft,state.fields,{hiddenFields,currencies});if(issue)return issue;const unique={channels:'渠道代码',dict:'字典编号',platforms:'平台名称'}[key];if(unique&&db[key].some(r=>r.uid!==state.rowId&&r[unique]===draft[unique]))return {field:unique,message:`${unique}已存在`};return null;}
function showFormError(fid,error){const form=$('#'+fid);if(!form)return;form.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));const box=form.querySelector('.error-msg');box.hidden=false;box.textContent=error.message;const field=[...form.querySelectorAll('[data-field]')].find(e=>e.dataset.field===error.field);const control=field&&[...field.querySelectorAll('input,select,textarea,button,[contenteditable]')].find(e=>!e.disabled&&!e.hidden&&e.getClientRects().length);if(control)control.setAttribute('aria-invalid','true');box.scrollIntoView({block:'nearest'});(control||box).focus({preventScroll:true});toast(error.message,true);}
function saveForm(fid){const state=forms.get(fid);if(!state)return;const draft=readForm(fid);const error=validation(state.key,draft,state);if(error)return showFormError(fid,error);const key=state.key;const ok=commit((state.rowId?'编辑':'新增')+SCHEMA[key].name,()=>{draft.uid=state.rowId||Model.uid();draft['更新时间']=dateNow();draft['创建时间']||=dateNow();draft['创建人']||='演示运营';draft['操作人']='演示运营';if(SCHEMA[key].columns.includes('ID'))draft.ID||=Model.uid('DEMO');if(key==='products'){draft['商品ID']||=Model.uid('DEMO');draft['库存']||=0;draft['销量']||=0;draft['N币售价']='';draft['雷神币售价']='';(draft['币种价格']||[]).forEach(c=>draft[c.currency+'售价']=Number(c.price));}if(key==='recommend')draft['选择商品']||=[];if(key==='roles')draft['角色ID']||=Model.uid('ROLE');if(key==='promotions')draft['活动ID']||=Model.uid('EVENT');if(key==='blacklist'){draft['状态']=draft['权限限制'].includes('解除拉黑')?'正常':draft['权限限制'].join(' / ');draft['更新人']='演示运营';}if(key==='auth')draft['生效模块']=draft['生效范围']==='全部'?'全部':draft['选择模块'];if(key==='dictItems'&&draft['key类型']==='图片')draft.key=draft['key图片']||'';const saved=Model.fromForm(db,key,draft),i=db[key].findIndex(r=>r.uid===state.rowId);if(i>=0)db[key][i]=saved;else db[key].unshift(saved);});if(ok){closeModal($('#'+fid).closest('.overlay').id);forms.delete(fid);render();toast('保存成功');}else showFormError(fid,{message:'保存失败：'+lastCommitError});}
function pickedHtml(ids,fid){return ids.map(id=>{const p=db.products.find(p=>p.uid===id);return p?`<div class="inline"><span style="flex:1">${esc(p['商品名称'])} <small>${esc(p['商品ID'])} · ${esc(p['账号类型'])}</small></span><input type="number" min="0" aria-label="商品排序 ${esc(p['商品名称'])}" data-picked-sort="${esc(id)}" data-form="${fid}" value="${forms.get(fid)?.draft['商品排序']?.[id]||0}" style="width:85px"><button type="button" class="link-btn danger" data-action="unpick" data-form="${fid}" data-id="${esc(id)}">移除</button></div>`:'';}).join('')||'<div class="muted" style="padding:10px 0">尚未选择商品</div>';}
function currencyHtml(value,fid){return (Array.isArray(value)?value:[]).map((c,i)=>`<div class="inline currency-row"><select aria-label="币种">${['N币','雷神币'].map(n=>`<option ${c.currency===n?'selected':''}>${n}</option>`).join('')}</select><input aria-label="币种售价" placeholder="售价" type="number" min="0" step="any" value="${esc(c.price)}" required><input aria-label="币种原价" placeholder="原价" type="number" min="0" step="any" value="${esc(c.original)}" required><button class="row-remove" type="button" data-action="removeCurrency">移除</button></div>`).join('');}
function getCurrencies(fid){return $$('#'+fid+' .currency-row').map(row=>({currency:row.querySelector('select').value,price:Number(row.querySelectorAll('input')[0].value),original:Number(row.querySelectorAll('input')[1].value)}));}
function picker(fid){const state=forms.get(fid),picked=new Set(state.draft['选择商品']||[]),data=db.products.filter(p=>p.uid!==state.rowId&&p['商品类型']==='独立商品');const id=modal('选择商品',`<div class="filters" style="padding:0 0 18px;grid-template-columns:2fr 1fr"><label class="field"><span>商品名称 / 商品ID</span><input id="pickerSearch" placeholder="搜索商品"></label><label class="field"><span>账号类型</span><select id="pickerType"><option value="">全部</option><option>CDK</option><option>账号</option></select></label></div><div id="pickerTable"></div>`,`<span id="pickerCount" class="muted" style="margin-right:auto"></span><button class="btn" data-action="close">取消</button><button class="btn primary" id="pickerConfirm">确认添加</button>`,true);
 function draw(){const q=$('#pickerSearch').value.toLowerCase(),type=$('#pickerType').value;const list=data.filter(p=>(p['商品名称']+p['商品ID']).toLowerCase().includes(q)&&(!type||p['账号类型']===type));$('#pickerTable').innerHTML=`<table><thead><tr><th>选择</th><th>商品ID</th><th>商品名称</th><th>账号类型</th><th>人民币售价</th><th>状态</th></tr></thead><tbody>${list.map(p=>`<tr><td><input type="checkbox" data-pick="${p.uid}" aria-label="选择 ${esc(p['商品名称'])}" ${picked.has(p.uid)?'checked':''}></td><td>${esc(p['商品ID'])}</td><td>${esc(p['商品名称'])}</td><td>${esc(p['账号类型'])}</td><td>¥ ${p['人民币售价']}</td><td>${badge(p['状态'])}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无匹配商品</td></tr>'}</tbody></table>`;$('#pickerCount').textContent='已选 '+picked.size+' 个';}
 $('#pickerSearch').oninput=draw;$('#pickerType').onchange=draw;$('#pickerTable').onchange=e=>{if(!e.target.dataset.pick)return;e.target.checked?picked.add(e.target.dataset.pick):picked.delete(e.target.dataset.pick);$('#pickerCount').textContent='已选 '+picked.size+' 个';};$('#pickerConfirm').onclick=()=>{state.draft['选择商品']=[...picked];$('#picked-'+fid).innerHTML=pickedHtml([...picked],fid);closeModal(id);};draw();}

function rowAction(key,id,op){const row=db[key].find(r=>r.uid===id);if(!row)return;const links={'版本管理':'versions','子分类':'subcategories','货源管理':'sources','批次管理':'batches','库存管理':'stock','字典配置':'dictItems'};
 if(op==='编辑')return openForm(key,id);
 if(links[op]){const target=key==='suppliers'&&row['合作方式']==='接口'?'apiSources':links[op];return navigate(target,{parent:id,name:rowName(key,row),...(key==='sources'&&target==='stock'?{source:'1'}:{})});}
 if(op==='供货商管理')return productSuppliers(id);
 if(op==='详情')return details(key,row);
 if(op==='授权')return permissionsForm(row);
 if(op==='成员管理')return membersForm(row);
 if(op==='新增子菜单')return openForm('permissions',null,{'菜单类型':'子菜单','父级菜单':row.uid});
 if(op==='商品导入')return importStock(row);
 if(op==='加入黑名单')return confirmAction('加入黑名单',`将 ${row['手机号']} 加入演示黑名单？`,()=>{if(db.blacklist.some(x=>x['手机号']===row['手机号']))return toast('该用户已在黑名单中',true);if(commit('加入黑名单',()=>db.blacklist.push({uid:'local-'+Date.now(),'手机号':row['手机号'],'状态':'黑名单','备注':'用户中心加入','创建时间':dateNow(),'创建人':'演示运营'})))toast('已加入黑名单');});
 if(op==='删除'){const references=Model.references(db,key,id);if(references.length)return modal('无法删除'+SCHEMA[key].name,`<p>请先处理以下关联后再删除：</p><ul>${references.slice(0,12).map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${references.length>12?`<p>另有 ${references.length-12} 处关联。</p>`:''}`,'<button class="btn" data-action="close">关闭</button>');return confirmAction('删除'+SCHEMA[key].name,`确认删除“${rowName(key,row)}”？`,()=>{if(commit('删除'+SCHEMA[key].name,()=>{db[key]=db[key].filter(r=>r.uid!==id);if(key==='roles')delete db.rolePermissions[id];db.trash.unshift({key,row,deletedAt:dateNow()});})){render();toast('已删除');}});}
 if(['启禁','上下架','开关','活动状态'].includes(op)){const change=Model.statusAction(key,row);if(!change)return;return confirmAction(change.next+SCHEMA[key].name,`确认将“${rowName(key,row)}”设为${change.next}？`,()=>{if(commit(change.next+SCHEMA[key].name,()=>{row[change.field]=change.next;row['更新时间']=dateNow();})){render();toast('状态已更新');}});}
}
function details(key,row){const cols=SCHEMA[key].columns;let body='';if(key==='refunds'){body=`<div class="steps">${['申请退款','主管审核','财务审核','退款处理中','财务打款','退款结束'].map((s,i)=>`<div class="step done"><strong>${i+1}. ${s}</strong>${i===5?esc(row['退款状态']):'已完成'}</div>`).join('')}</div><h3 class="section-title">退款信息</h3>`;}if(key==='orders')body='<div class="notice">订单详情为演示数据结构。实际测试后台当前未返回订单记录。</div>';
 body+=`<dl class="detail-grid">${cols.map(c=>`<div><dt>${esc(c)}</dt><dd>${/状态/.test(c)?badge(fmt(row[c])):esc(fmt(row[c]))}</dd></div>`).join('')}</dl>`;if(key==='refunds'){const order=db.orders.find(o=>o['订单编号']===row['订单编号']);if(order)body+=`<h3 class="section-title">订单信息</h3><dl class="detail-grid">${['订单编号','买家手机号','订单金额（元）','实付金额(元)','支付方式','下单时间'].map(c=>`<div><dt>${c}</dt><dd>${esc(fmt(order[c]))}</dd></div>`).join('')}</dl>`;}modal(SCHEMA[key].name+'详情',body,'<button class="btn" data-action="close">关闭</button>',true);}
function productSuppliers(productId){const product=db.products.find(x=>x.uid===productId);const mid=modal('供货商管理 · '+product['商品名称'],'<div id="supplierBindings"></div><div class="section-title">新增供货商</div><div class="form-grid"><label class="field"><span>合作方式</span><select id="bindMode"><option>导入</option><option>接口</option></select></label><label class="field"><span>供货商</span><select id="bindSupplier"></select></label><label class="field span2"><span>关联货源</span><select id="bindSource"></select></label></div>','<button class="btn" data-action="close">关闭</button><button class="btn primary" id="addBinding">新增供货商</button>',true);
 const updateProduct=()=>{product['供货商信息']=db.productSuppliers.filter(b=>b.productId===productId).map(b=>db.suppliers.find(s=>s.uid===b.supplierId)?.['供货商']).filter(Boolean).join('、')||'—';};
 function draw(){const bindings=db.productSuppliers.filter(b=>b.productId===productId);$('#supplierBindings').innerHTML=`<div class="table-wrap"><table><thead><tr>${['供货商','合作方式','票务类型','合同期','商品库存','状态','排序','操作'].map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${bindings.map(b=>{const s=db.suppliers.find(s=>s.uid===b.supplierId),source=db.sources.find(s=>s.uid===b.sourceId);return `<tr><td>${esc(s?.['供货商'])}</td><td>${esc(s?.['合作方式'])}</td><td>${esc(s?.['票务类型'])}</td><td>${esc(s?.['合同期'])}</td><td>${source?.['商品库存']||0}</td><td>${badge(b['状态'])}</td><td><input type="number" min="0" value="${b['排序']}" aria-label="供货商排序" data-sort-bind="${b.uid}" style="width:75px"></td><td><button class="link-btn" data-toggle-bind="${b.uid}">${b['状态']==='启用'?'禁用':'启用'}</button><button class="link-btn" data-stock-bind="${b.sourceId}">库存管理</button><button class="link-btn danger" data-remove-bind="${b.uid}">删除</button></td></tr>`;}).join('')||'<tr><td colspan="8" class="empty">暂无关联供货商</td></tr>'}</tbody></table></div>`;}
 function supplierChoices(){const ss=db.suppliers.filter(s=>s['合作方式']===$('#bindMode').value);$('#bindSupplier').innerHTML='<option value="">请选择供货商</option>'+ss.map(s=>`<option value="${s.uid}">${esc(s['供货商'])}</option>`).join('');selectAvailability($('#bindSupplier'),'该合作方式暂无供货商');sourceChoices();}
 function sourceChoices(){$('#bindSource').innerHTML='<option value="">请选择货源</option>'+db.sources.filter(s=>s.parentId===$('#bindSupplier').value).map(s=>`<option value="${s.uid}">${esc(s['商品名称'])} · ${esc(s['商品ID'])}</option>`).join('');selectAvailability($('#bindSource'),$('#bindSupplier').value?'该供货商暂无货源':'请先选择供货商');if(typeof SelectControls!=='undefined')SelectControls.refresh($('#'+mid));}
 $('#bindMode').onchange=supplierChoices;$('#bindSupplier').onchange=sourceChoices;$('#addBinding').onclick=()=>{const sid=$('#bindSupplier').value,sourceId=$('#bindSource').value;if(!sid||!sourceId)return toast('请选择供货商和货源',true);if(db.productSuppliers.some(b=>b.productId===productId&&b.supplierId===sid))return toast('该供货商已关联',true);if(commit('新增商品供货商',()=>{db.productSuppliers.push({uid:'bind-'+Date.now(),productId,supplierId:sid,sourceId,'排序':0,'状态':'启用'});updateProduct();})){draw();render();toast('供货商已关联');}};
 $('#supplierBindings').onchange=e=>{const b=db.productSuppliers.find(b=>b.uid===e.target.dataset.sortBind);if(b&&Number(e.target.value)>=0)commit('调整供货商排序',()=>b['排序']=Number(e.target.value));};
 $('#supplierBindings').onclick=e=>{const d=e.target.dataset;if(d.stockBind){closeModal(mid);return navigate('stock',{parent:d.stockBind,name:product['商品名称'],source:'1'});}if(d.toggleBind){const b=db.productSuppliers.find(b=>b.uid===d.toggleBind);if(commit('切换供货商状态',()=>b['状态']=b['状态']==='启用'?'禁用':'启用')){draw();render();}}if(d.removeBind)confirmAction('移除供货商','确认移除此商品与供货商的关联？',()=>{if(commit('移除商品供货商',()=>{db.productSuppliers=db.productSuppliers.filter(b=>b.uid!==d.removeBind);updateProduct();})){draw();render();}});};draw();supplierChoices();}
function permissionsForm(role){const selected=new Set(db.rolePermissions[role.uid]||[]);const mid=modal('角色授权 · '+role['角色名称'],`<div class="notice">配置原型中的角色授权数据，不会修改真实系统权限。</div><label class="inline" style="margin-bottom:15px"><input id="permissionAll" type="checkbox">全选</label><div id="permissionTree">${db.permissions.map(p=>`<label class="tree-row inline" style="padding-left:${p['菜单类型']==='一级菜单'?12:38}px"><input type="checkbox" value="${esc(p.uid)}" ${selected.has(p.uid)?'checked':''}><span>${esc(p['权限名称'])}</span><small>${esc(p['菜单类型'])}</small></label>`).join('')}</div>`,'<button class="btn" data-action="close">取消</button><button class="btn primary" id="savePermissions">保存授权</button>');const syncAll=()=>{const boxes=$$('#permissionTree input'),count=boxes.filter(x=>x.checked).length,all=$('#permissionAll');all.checked=boxes.length>0&&count===boxes.length;all.indeterminate=count>0&&count<boxes.length;all.disabled=!boxes.length;};$('#permissionAll').onchange=e=>{$$('#permissionTree input').forEach(x=>x.checked=e.target.checked);syncAll();};$('#permissionTree').onchange=syncAll;syncAll();$('#savePermissions').onclick=()=>{if(commit('角色授权',()=>db.rolePermissions[role.uid]=$$('#permissionTree input:checked').map(e=>e.value))){closeModal(mid);toast('授权已保存');}};}
function membersForm(role){const mid=modal('成员管理 · '+role['角色名称'],`<div id="roleMembers" class="stack">${db.admins.map(a=>`<label class="inline"><input type="checkbox" value="${a.uid}" ${(a.refs['角色']||[]).includes(role.uid)?'checked':''}>${esc(a['姓名'])} <small>${esc(a['账号'])}</small></label>`).join('')}</div>`,'<button class="btn" data-action="close">取消</button><button class="btn primary" id="saveMembers">保存成员</button>');$('#saveMembers').onclick=()=>{const ids=$$('#roleMembers input:checked').map(e=>e.value);if(commit('调整角色成员',()=>db.admins.forEach(a=>{a.refs['角色']=(a.refs['角色']||[]).filter(r=>r!==role.uid);if(ids.includes(a.uid))a.refs['角色'].push(role.uid);}))){closeModal(mid);toast('角色成员已保存');}};}
function authGlobalHtml(){return `<section class="panel panel-pad"><div class="inline"><label><input id="authEnabled" type="checkbox" ${db.authGlobal.enabled?'checked':''}>开启实名认证</label><label style="margin-left:20px">生效模块 <select id="authScope" style="width:110px"><option ${db.authGlobal.scope==='全部'?'selected':''}>全部</option><option ${db.authGlobal.scope==='部分'?'selected':''}>部分</option></select></label><select id="authModules" aria-label="全局生效模块" style="width:130px" ${db.authGlobal.scope==='全部'?'hidden':''}><option>生成订单实名</option></select><button class="btn primary" data-action="saveAuth">保存配置</button></div></section>`;}
function renderCardQuery(){const logs=activeSubtab==='logs';$('#content').innerHTML=`<div class="page-head"><div><h1>订单卡密查询</h1><p>仅查询虚构演示订单，所有演示查询记录可追溯。</p></div></div><section class="panel panel-pad"><div class="tabs"><button class="${!logs?'active':''}" data-action="queryTab" data-tab="query">卡密查询</button><button class="${logs?'active':''}" data-action="queryTab" data-tab="logs">查询记录</button></div>${logs?simpleTable(db.queryLogs,['订单编号','查询时间','查询人']):`<form id="cardQueryForm" novalidate><label class="field"><span>订单编号</span><textarea id="cardOrder" required placeholder="请输入订单编号，如 ORDER-DEMO-001；每行一个"></textarea></label><div class="btn-row" style="margin-top:15px"><button class="btn primary">查询</button><button class="btn" type="button" data-action="resetCardQuery">重置</button></div></form><div id="cardResult" style="margin-top:20px"></div>`}</section>`;}
function importStock(batch){const mid=modal('商品导入 · '+batch.ID,`<div class="notice">原后台支持 Excel 模板导入；此静态原型使用 CSV / TXT 或粘贴内容演示入库流程，每行一个虚构 CDKEY。重复码会跳过。</div><div class="btn-row"><button class="btn" id="stockTemplate">下载演示模板</button></div><label class="field" style="margin-top:16px"><span>选择文件</span><input type="file" id="stockFile" accept=".csv,.txt"></label><label class="field" style="margin-top:16px"><span class="required">CDKEY</span><textarea id="stockCodes" placeholder="DEMO-NOT-VALID-0001&#10;DEMO-NOT-VALID-0002"></textarea></label>`,'<button class="btn" data-action="close">取消</button><button class="btn primary" id="importStockConfirm">确认导入</button>');$('#stockTemplate').onclick=()=>download('卡密导入演示模板.csv','CDKEY\nDEMO-NOT-VALID-0001\n','text/csv');$('#stockFile').onchange=async e=>{const file=e.target.files[0];if(file)$('#stockCodes').value=await file.text();};$('#importStockConfirm').onclick=()=>{let result;if(commit('导入商品库存',()=>result=Model.addStock(db,batch.uid,$('#stockCodes').value))){closeModal(mid);render();toast(`导入 ${result.added} 条，跳过重复 ${result.skipped} 条`);}};}

function download(name,text,type='application/json'){const blob=new Blob([type==='text/csv'?'\ufeff':'',text],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(data,cols){const cell=v=>'"'+String(fmt(v)).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';return [cols.map(cell).join(','),...data.map(r=>cols.map(c=>cell(r[c])).join(','))].join('\r\n');}
function exportList(){const list=filteredRows(),name=SCHEMA[current].name;download(name+'-演示数据.csv',csv(list,SCHEMA[current].columns),'text/csv');commit('导出'+name,()=>db.exportJobs.unshift({'文件名':name+'-演示数据.csv','记录数':list.length,'状态':'已完成','创建时间':dateNow()}));toast('列表已导出');}
function stats(){const data=filteredRows(),paid=data.filter(r=>r['支付状态']==='已支付'),amount=paid.reduce((sum,r)=>sum+Number(r['实付金额(元)']||0),0),job={'订单数':data.length,'已支付订单':paid.length,'实付合计':amount.toFixed(2),'创建时间':dateNow()};commit('订单统计',()=>db.statJobs.unshift(job));modal('订单统计',`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${[['订单数量',data.length],['已支付',paid.length],['实付合计（元）',amount.toFixed(2)]].map(v=>`<div class="stat"><div><small>${v[0]}</small><strong>${v[1]}</strong></div></div>`).join('')}</div><p class="muted">按当前查询条件统计演示数据。</p>`,'<button class="btn" data-action="close">关闭</button>',true);}
function dataTools(){const original=recoveryRaw||localStorage.getItem(STORAGE+'-recovery');const mid=modal('原型数据',`<div class="notice">当前操作只影响本浏览器中的演示数据。导出文件可用于备份或在其他浏览器恢复。</div><div class="tool-list">${original?`<div class="notice">${esc(startupNotice||'保留了一份升级或恢复前的原始数据。')}<button class="btn small" id="downloadRecovery">导出原始备份</button></div>`:''}<div class="inline"><div style="flex:1"><strong>导出全部演示数据</strong><p class="muted">包括配置、库存、查询记录和原型操作记录</p></div><button class="btn" id="backupData">导出 JSON</button></div><div><label class="field"><span>导入原型备份</span><input type="file" id="restoreData" accept=".json"></label></div><div class="inline"><div style="flex:1"><strong>恢复初始演示数据</strong><p class="muted">清除当前浏览器中的修改</p></div><button class="btn danger" id="resetData">恢复演示数据</button></div><div><h3>原型操作记录</h3>${simpleTable(db.audit.slice(0,20).map(r=>({'时间':r.time,'操作':r.action,'操作人':r.operator})),['时间','操作','操作人'])}</div></div>`,'<button class="btn" data-action="close">关闭</button>',true);if(original)$('#downloadRecovery').onclick=()=>download('independent-admin-original.json',original);$('#backupData').onclick=()=>download('independent-admin-backup.json',JSON.stringify(db,null,2));$('#resetData').onclick=()=>confirmAction('恢复演示数据','当前浏览器内的原型修改将被初始演示数据覆盖。确认恢复？',()=>{if(commit('恢复演示数据',()=>db=Model.prepare(makeSeed()))){closeModal(mid);render();toast('已恢复初始数据');}});$('#restoreData').onchange=async e=>{try{if(!e.target.files[0])return;const imported=Model.prepare(JSON.parse(await e.target.files[0].text()));confirmAction('导入备份','使用此备份覆盖当前原型数据？',()=>{if(commit('导入备份',()=>db=imported)){closeModal(mid);render();toast('备份已导入');}});}catch(error){toast('备份未导入：'+error.message,true);}};}
function trash(){const mid=modal('字典回收站',`<div id="trashRows">${db.trash.filter(t=>t.key==='dict').map((t,i)=>`<div class="inline" style="padding:12px;border-bottom:1px solid #e5eaf2"><span style="flex:1">${esc(t.row['字典名称'])} <small>${t.deletedAt}</small></span><button class="btn small" data-restore="${esc(t.row.uid)}">还原</button></div>`).join('')||'<div class="empty">回收站为空</div>'}</div>`,'<button class="btn" data-action="close">关闭</button>');$('#trashRows').onclick=e=>{const id=e.target.dataset.restore;if(!id)return;const item=db.trash.find(t=>t.row.uid===id&&t.key==='dict');if(commit('还原数据字典',()=>{db.dict.push(item.row);db.trash=db.trash.filter(t=>t!==item);})){closeModal(mid);render();trash();}};}
function dictImport(){const mid=modal('导入数据字典',`<p class="muted">粘贴演示 JSON 数组，字段：字典名称、字典编号、描述、字典类型。已存在的编号会跳过。</p><textarea id="dictJson" style="margin-top:14px;min-height:170px" placeholder='[{"字典名称":"测试字典","字典编号":"demo_new","描述":"","字典类型":"字符串"}]'></textarea>`,'<button class="btn" data-action="close">取消</button><button class="btn primary" id="dictImportConfirm">导入</button>');$('#dictImportConfirm').onclick=()=>{try{const rows=JSON.parse($('#dictJson').value);if(!Array.isArray(rows)||rows.some(r=>!r['字典名称']||!r['字典编号']))throw Error();let count=0;if(commit('导入数据字典',()=>{for(const r of rows)if(!db.dict.some(d=>d['字典编号']===r['字典编号'])){db.dict.push({...r,uid:Model.uid('dict'),refs:{}});count++;}})){closeModal(mid);render();toast('已导入 '+count+' 条');}}catch{toast('请检查 JSON 格式及必填字段',true);}};}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;switch(a){case'steamLookup':{const form=$('#'+b.dataset.form),game=db.games.find(g=>g.steamId===form.elements.namedItem('steamId').value);if(!game)return toast('未找到演示资料，可输入 DEMO-STEAM-1 或手动填写',true);for(const n of ['游戏名称','游戏标签','游戏副标题','游戏别名'])if(form.elements.namedItem(n))form.elements.namedItem(n).value=game[n]||'';toast('已填充本地演示资料');return;}case'addPlatform':$('#platforms-'+b.dataset.form).insertAdjacentHTML('beforeend',platformRows([{}]));return;case'removePlatform':return b.closest('.platform-binding').remove();case'syncSources':if(commit('模拟接口货源同步',()=>{db.apiSources=db.sources.filter(r=>db.suppliers.find(s=>s.uid===r.parentId)?.['合作方式']==='接口').map(r=>({...r,'三方商品ID':'THIRD-DEMO-'+r.uid,'商品状态':r['状态']}));})){render();toast('演示货源目录已同步');}return;case'close':return closeModal(b.closest('.overlay').id);case'new':return openForm(current);case'productColumns':showAllProductColumns=!showAllProductColumns;return render();case'row':return rowAction(b.dataset.key,b.dataset.id,b.dataset.op);case'resetFilters':filters={};page=1;return render();case'page':page+=Number(b.dataset.delta);return render();case'export':return exportList();case'stats':return stats();case'statJobs':return modal('统计列表',simpleTable(db.statJobs,['订单数','已支付订单','实付合计','创建时间']),'<button class="btn" data-action="close">关闭</button>',true);case'exportJobs':return modal('导出记录',simpleTable(db.exportJobs,['文件名','记录数','状态','创建时间']),'<button class="btn" data-action="close">关闭</button>',true);case'backParent':return goParent();case'columns':return navigate('columns');case'picker':return picker(b.dataset.form);case'unpick':{const st=forms.get(b.dataset.form);st.draft['选择商品']=st.draft['选择商品'].filter(x=>x!==b.dataset.id);$('#picked-'+b.dataset.form).innerHTML=pickedHtml(st.draft['选择商品'],b.dataset.form);return;}case'addCurrency':{const id=b.dataset.form,rows=getCurrencies(id);if(rows.length>=2)return toast('已配置全部可选币种',true);rows.push({currency:rows.some(r=>r.currency==='N币')?'雷神币':'N币',price:0,original:0});$('#currencies-'+id).innerHTML=currencyHtml(rows,id);return;}case'removeCurrency':return b.closest('.currency-row').remove();case'queryTab':activeSubtab=b.dataset.tab;return renderCardQuery();case'stockTab':activeSubtab=b.dataset.tab;filters={};page=1;return render();case'resetCardQuery':return ListInteractions.resetCardQuery($('#cardQueryForm'),$('#cardResult'));case'saveAuth':if(commit('保存实名认证配置',()=>db.authGlobal={enabled:$('#authEnabled').checked,scope:$('#authScope').value,modules:[$('#authModules').value]}))toast('实名认证演示配置已保存');return;case'trash':return trash();case'dictImport':return dictImport();case'cache':commit('刷新原型字典缓存',()=>{});toast('原型字典已刷新（不调用服务端缓存）');return;}});
document.addEventListener('submit',e=>{if(e.target.id==='filterForm'){e.preventDefault();filters={};const form=e.target;for(const f of activeSchema().filters){filters[f.label]=f.type==='range'?[form.elements.namedItem(f.label+'开始').value,form.elements.namedItem(f.label+'结束').value]:form.elements.namedItem(f.label)?.value||'';}page=1;return render();}if(e.target.matches('.record-form')){e.preventDefault();return saveForm(e.target.id);}if(e.target.id==='cardQueryForm'){e.preventDefault();const ids=[...new Set($('#cardOrder').value.split(/[\n,，]/).map(s=>s.trim()).filter(Boolean))];if(!ids.length){$('#cardResult').innerHTML='<div class="error-msg" role="alert">请输入订单编号</div>';$('#cardOrder').focus();return;}const result=ids.map(id=>{const order=db.orders.find(o=>o['订单编号']===id);return {'订单编号':id,'商品名称':order?.['商品名称']||'—','查询结果':!order?'未找到订单':order['支付状态']!=='已支付'?'订单未支付':order['订单状态']==='已退款'?'订单已退款':'DEMO-NOT-VALID-'+id.slice(-3)};});if(commit('查询演示卡密',()=>db.queryLogs.unshift(...ids.map(id=>({'订单编号':id,'查询时间':dateNow(),'查询人':'演示运营'})))))$('#cardResult').innerHTML=simpleTable(result,['订单编号','商品名称','查询结果']);}});
document.addEventListener('change',async e=>{if(e.target.dataset.pickedSort){const st=forms.get(e.target.dataset.form);st.draft['商品排序']||={};st.draft['商品排序'][e.target.dataset.pickedSort]=Number(e.target.value);}if(e.target.id==='pageSize'){pageSize=Number(e.target.value);page=1;render();}if(e.target.id==='authScope')$('#authModules').hidden=e.target.value==='全部';const form=e.target.closest('.record-form');if(form)updateDependencies(form.id,e.target.name);if(e.target.dataset.upload){const state=forms.get(e.target.dataset.form),name=e.target.dataset.upload,file=e.target.files[0];if(!file)return;if(file.type.startsWith('image/')){if(file.size>2*1024*1024){e.target.value='';return toast('图片不能超过 2 MB',true);}const reader=new FileReader();reader.onload=()=>{state.draft[name]=reader.result;const preview=e.target.parentElement.querySelector('[data-preview]');preview.innerHTML=`<img class="preview-img" src="${esc(reader.result)}" alt="图片预览">`;};reader.readAsDataURL(file);}else{state.draft[name]=file.name;e.target.parentElement.querySelector('[data-preview]').textContent=file.name;}}});
document.addEventListener('keydown',e=>{if(e.defaultPrevented)return;if(e.key==='Escape'&&$$('.overlay').length)closeModal();if(e.key==='Tab'&&$$('.overlay').length){const active=$$('.overlay').at(-1),focusable=[...active.querySelectorAll('button,input,select,textarea,a')].filter(e=>!e.disabled&&e.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
$('#menuSearch').oninput=renderNav;$('#dataTools').onclick=dataTools;window.addEventListener('hashchange',route);route();SelectControls.init();if(startupNotice)modal('原型数据检查',`<p>${esc(startupNotice)}</p><p>可通过右上角“原型数据”导出原始备份。</p>`,'<button class="btn" data-action="close">知道了</button>');

function safeRich(html){const t=document.createElement('template');t.innerHTML=String(html||'');t.content.querySelectorAll('script,style,iframe,object,img,video,audio,svg').forEach(e=>e.remove());t.content.querySelectorAll('*').forEach(e=>{[...e.attributes].forEach(a=>e.removeAttribute(a.name));if(!['B','STRONG','I','EM','U','P','BR','UL','OL','LI','DIV'].includes(e.tagName))e.replaceWith(...e.childNodes);});return t.innerHTML;}
function platformRows(rows){return rows.map(r=>`<div class="inline platform-binding"><select aria-label="平台名称">${options('platforms',r.platform)}</select><input aria-label="平台游戏ID" placeholder="平台游戏ID" value="${esc(r.gameId||'')}"><button class="btn small" type="button" data-action="removePlatform">移除</button></div>`).join('');}
document.addEventListener('mousedown',e=>{const b=e.target.closest('[data-rich-command]');if(b){e.preventDefault();b.closest('.rich-wrap').querySelector('.rich-editor').focus();document.execCommand(b.dataset.richCommand,false,null);}});
document.addEventListener('paste',e=>{if(e.target.closest('.rich-editor')){e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));}});

function goParent(){const context=Model.parentContext(db,currentRoute);let key=context.parentKey||'products';const parent=context.parent,grandKey=SCHEMA[key]?.parent,grand=grandKey&&Model.get(db,grandKey,parent?.parentId);if(!parent){while(SCHEMA[key]?.parent)key=SCHEMA[key].parent;return navigate(key);}if(key==='sources'&&Model.get(db,'suppliers',grand?.uid)?.['合作方式']==='接口')key='apiSources';navigate(key,grand?{parent:grand.uid}:{});}
